// Advanced function bits
// 280: Bit13 = external relay enable

msg.baseAddr = 280;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 280,
    quantity: 1
};
return msg;

// External relay bitmap
// 296: 外部继电器位 Bit0-8 = 8 relay positions

msg.baseAddr = 296;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 296,
    quantity: 1
};
return msg;

// Build ExternalRelayConfigState from Modbus reads.
//
// Registers:
// 280: Advanced function bits (Bit13 = external relay enable)
// 296: External relay bitmap (Bit0-8 = 8 relay positions)

let raw = msg.payload;
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (typeof raw === "string" || !Array.isArray(data)) {
    return null;
}

let baseAddr = msg.baseAddr;
if (typeof baseAddr !== "number") {
    baseAddr = (msg.modbusRequest && msg.modbusRequest.address);
}
if (typeof baseAddr !== "number") {
    node.warn("ExternalRelayConfigState: missing base address");
    return null;
}

// ---- Store partials ----

// Advanced bits 280
if (baseAddr === 280) {
    const bits = data[0] || 0;
    const externalRelayEnabled = ((bits >> 13) & 0x01) === 1;

    flow.set("erc_part_adv_bits", {
        advBitsRaw: bits,
        externalRelayFeatureEnabled: externalRelayEnabled
    });
}

// Relay bitmap 296
else if (baseAddr === 296) {
    flow.set("erc_part_relay_bitmap", {
        relayBitmapRaw: data[0] || 0
    });
}
else {
    return null;
}

// ---- Try to assemble ----

const advBitsPart = flow.get("erc_part_adv_bits");
const relayBitmapPart = flow.get("erc_part_relay_bitmap");

if (!advBitsPart || !relayBitmapPart) {
    return null;
}

// Default relay roles (can be customized)
const defaultRelayRoles = [
    { relayId: 1, logicalRole: "generator_start", normallyOpen: true, description: "Generator start signal" },
    { relayId: 2, logicalRole: "alarm", normallyOpen: true, description: "Alarm output" },
    { relayId: 3, logicalRole: "dry_contact", normallyOpen: true, description: "Dry contact 1" },
    { relayId: 4, logicalRole: "dry_contact", normallyOpen: true, description: "Dry contact 2" },
    { relayId: 5, logicalRole: "spare", normallyOpen: true, description: "Spare relay 1" },
    { relayId: 6, logicalRole: "spare", normallyOpen: true, description: "Spare relay 2" },
    { relayId: 7, logicalRole: "spare", normallyOpen: true, description: "Spare relay 3" },
    { relayId: 8, logicalRole: "spare", normallyOpen: true, description: "Spare relay 4" }
];

// Build relays array with current state from bitmap
const bitmap = relayBitmapPart.relayBitmapRaw;
const relays = defaultRelayRoles.map((relay, index) => {
    const isActive = ((bitmap >> index) & 0x01) === 1;
    return {
        ...relay,
        isActive: isActive  // Current state from bitmap
    };
});

const gatewayId = global.get("GATEWAY_ID") || env.get("GATEWAY_ID") || "EC100-GW-001";
const inverterSN = global.get("INVERTER_SN") || env.get("INVERTER_SN") || "Unknown";

const state = {
    kind: "ExternalRelayConfigState",
    timestampUtc: new Date().toISOString(),
    gatewayId: gatewayId,
    inverterSerialNumber: inverterSN,
    version: "1",

    externalRelayFeatureEnabled: advBitsPart.externalRelayFeatureEnabled,
    relayBitmapRaw: relayBitmapPart.relayBitmapRaw,

    relays: relays,

    _debug: {
        advBitsRaw: advBitsPart.advBitsRaw,
        relayBitmapBinary: bitmap.toString(2).padStart(8, '0')
    }
};

// Clear partials
flow.set("erc_part_adv_bits", null);
flow.set("erc_part_relay_bitmap", null);

flow.set("externalRelayConfigSnapshot", state);

msg.payload = state;
msg.state = state;
return msg;
